tool_args.command:
# Check the issue columns: each is binary (yes/no), count how many events have each issue
curl -s "https://poldem.eui.eu/downloads/pea/poldem-protest_30.csv" 2>&1 | python3 -c "
import csv, sys
reader = csv.DictReader(sys.stdin)
issue_cols = ['issue_econ_private','issue_econ_public','issue_cult_lib','issue_environment','issue_political','issue_regional','issue_cult_cons','issue_xeno','issue_other','issue_dontknow','issue_missing']
counts = {c:0 for c in issue_cols}
total = 0
for row in reader:
    total += 1
    for c in issue_cols:
        if row.get(c,'').strip().lower() == 'yes':
            counts[c] += 1
print(f'Total rows: {total}')
for c in issue_cols:
    print(f'{c}: {counts[c]} ({100*counts[c]/total:.1f}%)')
"
